@pushOnce('styles')
<style>
.api-hero{background:linear-gradient(120deg,#1745bf,#3769f5);color:white;border-radius:22px;padding:30px;display:flex;justify-content:space-between;align-items:center;gap:24px;margin-bottom:24px}.api-hero h1{font-size:28px;margin:8px 0 12px}.api-hero p{color:#e0e9ff;max-width:640px;line-height:1.8}.api-hero .btn{background:white;color:#234ec1;border-color:transparent}.api-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(300px,1fr);gap:24px}.api-card{background:var(--dt-bg-ffffff,#fff);border:1px solid var(--dt-b-e2e8f0,#e2e8f0);border-radius:20px;padding:26px;margin-bottom:24px;min-width:0}.api-card h2{display:flex;align-items:center;gap:12px;font-size:19px;margin:0 0 20px}.api-card h2 svg{padding:9px;background:rgba(53,101,255,.09);width:40px;height:40px;border-radius:12px;color:#3565ff;flex-shrink:0}.api-card p,.api-card li{line-height:1.85}.api-card label{display:block;font-weight:600;margin:17px 0 9px}.api-card input,.api-card textarea,.api-card select{width:100%;box-sizing:border-box;min-height:44px;border-radius:10px;border:1px solid var(--dt-b-e2e8f0,#dbe3f0);background:var(--dt-bg-f8fafc,#f8fafc);color:inherit;padding:11px 13px;font:inherit}.api-card textarea{min-height:105px}.api-help{font-size:13px;color:var(--dt-t-64748b,#64748b);margin-top:9px;line-height:1.7}.api-info{display:grid;grid-template-columns:100px minmax(0,1fr);gap:14px;font-size:14px}.api-info dt{color:var(--dt-t-64748b,#64748b)}.api-info dd{margin:0;overflow-wrap:anywhere}.api-secret{background:rgba(53,101,255,.08);border:1px solid #7499ff;border-radius:14px;padding:18px;margin-bottom:20px}.api-secret code{display:block;overflow-wrap:anywhere;font-size:15px;margin:12px 0}.api-status{font-size:13px;border-radius:7px;padding:5px 10px;background:rgba(53,101,255,.1);color:#3565ff}.api-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.api-steps{counter-reset:step;list-style:none;padding:0}.api-steps li{counter-increment:step;position:relative;padding:0 0 20px 38px}.api-steps li:before{content:counter(step);position:absolute;left:0;top:3px;width:24px;height:24px;border-radius:7px;background:#edf2ff;color:#3565ff;text-align:center;font-weight:700;line-height:24px}.api-doc{max-width:100%;font-size:15px;line-height:1.85;overflow-wrap:anywhere}.api-doc h1{font-size:26px}.api-doc h2{font-size:20px;margin:28px 0 12px}.api-doc h3{font-size:17px}.api-doc pre{background:var(--dt-bg-f8fafc,#f3f6fc);border:1px solid var(--dt-b-e2e8f0,#dbe3f0);padding:18px;border-radius:12px;overflow:auto;font-size:13px}.api-doc table{width:100%;border-collapse:collapse;font-size:14px;display:block;overflow:auto}.api-doc td,.api-doc th{border:1px solid var(--dt-b-e2e8f0,#e2e8f0);padding:10px;text-align:left;min-width:90px}.api-doc code{font-family:ui-monospace,Consolas,monospace}.api-log-wrap{overflow:auto}.api-log-wrap table{min-width:650px}.api-review-item{margin-bottom:20px}.api-review-item summary{font-weight:600;cursor:pointer}.api-form-row{display:grid;grid-template-columns:1fr 1fr;gap:16px}@media(max-width:1000px){.api-grid{grid-template-columns:1fr}}@media(max-width:600px){.api-hero{padding:22px;display:block}.api-hero h1{font-size:23px}.api-card{padding:20px}.api-form-row{grid-template-columns:1fr}.api-info{grid-template-columns:80px minmax(0,1fr)}}
</style>
@endPushOnce
@pushOnce('scripts')
<script nonce="{{ $cspNonce ?? '' }}">document.addEventListener('click',async function(e){const b=e.target.closest('[data-api-copy]');if(!b)return;const el=document.getElementById(b.dataset.apiCopy);if(!el)return;try{await navigator.clipboard.writeText(el.textContent.trim());b.textContent='已复制';}catch(error){const range=document.createRange();range.selectNodeContents(el);const s=window.getSelection();s.removeAllRanges();s.addRange(range);b.textContent='已选中，请复制';}});</script>
@endPushOnce
